import { createSeededRandom } from "../_shared/no_count_it_scene/sceneGenerator.ts";
export interface NoCountItBackgroundAsset { name: string; dataUri: string; }
const BACKGROUND_ASSETS: readonly NoCountItBackgroundAsset[] = [
  { name: "background_1.png", dataUri: "data:image/png;base64," },
];
export function selectNoCountItBackground(seed: string): NoCountItBackgroundAsset {
  const random = createSeededRandom(`${seed}-background-image`);
  return BACKGROUND_ASSETS[Math.floor(random() * BACKGROUND_ASSETS.length)]!;
}
